def component_sizes(n: int, edges: list[tuple[int, int]]) -> list[int]:
    """A graph has nodes 0 .. n-1 and the undirected `edges` (pairs of node indices;
    duplicates and self-loops may occur). Every node belongs to exactly one
    connected component, so isolated nodes are components of size 1.

    Return the sizes of all connected components, largest first.

    >>> component_sizes(5, [(0, 1), (1, 2), (3, 4)])
    [3, 2]
    """
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    sizes = {}
    for v in range(n):
        r = find(v)
        sizes[r] = sizes.get(r, 0) + 1
    return sorted(sizes.values(), reverse=True)

