def digit_sum(n: int) -> int:
    """Return the sum of the decimal digits of `n`. The sign is ignored (-123 -> 6); 0 -> 0.

    >>> digit_sum(4096)
    19
    """
    return sum(int(c) for c in str(abs(n)))

