canonical_solution:
def lis_length(nums: list[int]) -> int:
    """Return the length of the longest non-increasing SUBSEQUENCE (elements kept in order, not necessarily adjacent).

    "non-increasing" compares each element with the previous one using '>='.
    A single element counts as length 1; an empty list gives 0.

    >>> lis_length([2, 2, 1, 3, 4])
    3
    """
    if not nums:
        return 0
    best = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] >= nums[i]:
                best[i] = max(best[i], best[j] + 1)
    return max(best)

