def arrange_rows(records: list[tuple[str, int, int]]) -> list[str]:
    """Each record is a (name, age, score) tuple. Return the names ordered by:

    1. age ascending;
    2. then, among equal age, by score ascending;
    3. records equal on both keys keep their original relative order.

    An empty list gives [].

    >>> arrange_rows([('ann', 30, 5), ('bo', 25, 9), ('cy', 30, 9)])
    ['bo', 'ann', 'cy']
    """

test_code:
def test_random_records():
    assert arrange_rows([('Bob', 20, 9), ('Dana', 20, 7), ('amy', 41, 7), ('Nia', 30, 7), ('gus', 41, 9), ('Finn', 20, 5)]) == ['Finn', 'Dana', 'Bob', 'Nia', 'amy', 'gus']

def test_ties_on_primary():
    assert arrange_rows([('Bob', 30, 7), ('Dana', 30, 5), ('amy', 30, 9), ('nia', 25, 7), ('GUS', 25, 7)]) == ['nia', 'GUS', 'Dana', 'Bob', 'amy']

def test_case_of_names():
    assert arrange_rows([('bob', 30, 7), ('Amy', 30, 7), ('carl', 30, 7), ('Dan', 30, 7)]) == ['bob', 'Amy', 'carl', 'Dan']

def test_duplicates_keep_order():
    assert arrange_rows([('x', 1, 1), ('y', 2, 2), ('x', 1, 1)]) == ['x', 'x', 'y']

def test_single():
    assert arrange_rows([('Bob', 20, 9)]) == ['Bob']

